  const copies = useResource<Row[]>(gestion ? '/ejemplares' : null), books = useResource<Row[]>('/catalogo'), catalogs = useResource<Row>('/catalogos')
  const all = rows(copies.data), shown = all.filter(e => !book || String(e.libro_id) === book), locked = editor && ['PRESTADO', 'RESERVADO'].includes(editor.estado)
